mapper.select:
SELECT COUNT(1) FROM tb_survey_answer
 WHERE question_id = #{questionId}
   AND answer_text IS NOT NULL AND answer_text != ''

mapper.delete:
DELETE FROM tb_survey_answer
WHERE answer_id = #{answerId}
AND updated_at <= DATE_SUB(NOW(), INTERVAL 1 MONTH)

DELETE FROM tb_survey_answer
 WHERE response_id IN (
   SELECT r.response_id FROM tb_survey_response r
    WHERE r.survey_id IN (
      SELECT s.survey_id FROM tb_survey s
       WHERE s.delete_yn = 'Y'
         AND s.updated_at <= #{cutoff}
    )
 )

mapper.select:
SELECT COUNT(*) FROM tb_survey_answer a
 WHERE a.response_id IN (
   SELECT r.response_id FROM tb_survey_response r
    WHERE r.survey_id IN (
      SELECT s.survey_id FROM tb_survey s
       WHERE s.delete_yn = 'Y'
         AND s.updated_at <= #{cutoff}
    )
 )
